META = dict(
    outline='ಶ್ಲೋಕಗಳು 1–2: ದೇಹ ಕ್ಷೇತ್ರ, ಅದನ್ನು ತಿಳಿಯುವವನು ಕ್ಷೇತ್ರಜ್ಞ; 3–6: ಕ್ಷೇತ್ರ ಯಾವುದರಿಂದ ಆಗಿದೆ; 7–11: ನಿಜವಾದ ಜ್ಞಾನದ ಇಪ್ಪತ್ತು ಲಕ್ಷಣಗಳು; 12–18: ತಿಳಿಯಬೇಕಾದ ಪರಮಾತ್ಮ, ಒಳಗೂ ಹೊರಗೂ, ದೂರದಲ್ಲೂ ಹತ್ತಿರದಲ್ಲೂ; 19–23: ಪ್ರಕೃತಿ ಮತ್ತು ಪುರುಷ; 24–26: ಅವನನ್ನು ಸೇರುವ ಬೇರೆ ಬೇರೆ ಮಾರ್ಗಗಳು; 27–34: ಎಲ್ಲರಲ್ಲೂ ಒಬ್ಬನೇ ಪರಮೇಶ್ವರನನ್ನು ಕಾಣುವವನೇ ನಿಜವಾಗಿ ಕಾಣುತ್ತಾನೆ.',
)
T = {
1: 'ಶ್ರೀಭಗವಂತ ಹೇಳಿದನು: ಹೇ ಕೌಂತೇಯ, ಈ ದೇಹವನ್ನು ಕ್ಷೇತ್ರ ಎನ್ನುತ್ತಾರೆ. ಇದನ್ನು ತಿಳಿಯುವವನನ್ನು, ಈ ವಿಷಯ ತಿಳಿದವರು ಕ್ಷೇತ್ರಜ್ಞ ಎನ್ನುತ್ತಾರೆ.',
3: 'ಆ ಕ್ಷೇತ್ರ ಏನು, ಹೇಗಿದೆ, ಅದರಲ್ಲಿ ಯಾವ ಬದಲಾವಣೆಗಳಿವೆ, ಅದು ಎಲ್ಲಿಂದ ಬಂದಿತು, ಮತ್ತು ಕ್ಷೇತ್ರಜ್ಞ ಯಾರು, ಅವನ ಪ್ರಭಾವ ಏನು, ಇದನ್ನೆಲ್ಲ ನನ್ನಿಂದ ಸಂಕ್ಷೇಪವಾಗಿ ಕೇಳು.',
4: 'ಇದನ್ನು ಋಷಿಗಳು ಅನೇಕ ರೀತಿಯಲ್ಲಿ, ಬೇರೆ ಬೇರೆ ಛಂದಸ್ಸುಗಳಲ್ಲಿ ಪ್ರತ್ಯೇಕವಾಗಿ ಹಾಡಿದ್ದಾರೆ. ಯುಕ್ತಿಯಿಂದ ನಿಶ್ಚಿತವಾಗಿ ಹೇಳಿದ ಬ್ರಹ್ಮಸೂತ್ರದ ಪದಗಳಲ್ಲೂ ಇದು ಇದೆ.',
5: 'ಪಂಚ ಮಹಾಭೂತಗಳು, ಅಹಂಕಾರ, ಬುದ್ಧಿ, ಅವ್ಯಕ್ತ (ಮೂಲ ಪ್ರಕೃತಿ), ಹತ್ತು ಇಂದ್ರಿಯಗಳು, ಮನಸ್ಸು ಮತ್ತು ಇಂದ್ರಿಯಗಳ ಐದು ವಿಷಯಗಳು,',
6: 'ಬಯಕೆ, ದ್ವೇಷ, ಸುಖ, ದುಃಖ, ದೇಹಸಮೂಹ, ಚೈತನ್ಯ ಮತ್ತು ಧೈರ್ಯ: ವಿಕಾರಗಳೊಂದಿಗೆ ಇದೇ ಕ್ಷೇತ್ರ ಎಂದು ಸಂಕ್ಷೇಪವಾಗಿ ಹೇಳಲಾಗಿದೆ.',
7: 'ಅಭಿಮಾನವಿಲ್ಲದಿರುವಿಕೆ, ದಂಭವಿಲ್ಲದಿರುವಿಕೆ, ಅಹಿಂಸೆ, ಕ್ಷಮೆ, ಸರಳತೆ, ಗುರುಸೇವೆ, ಶುಚಿತ್ವ, ಸ್ಥಿರತೆ, ಆತ್ಮಸಂಯಮ,',
8: 'ಇಂದ್ರಿಯ ವಿಷಯಗಳಲ್ಲಿ ವೈರಾಗ್ಯ, ಅಹಂಕಾರವಿಲ್ಲದಿರುವಿಕೆ, ಹುಟ್ಟು, ಸಾವು, ಮುಪ್ಪು, ರೋಗ ಮತ್ತು ದುಃಖದ ದೋಷವನ್ನು ಮತ್ತೆ ಮತ್ತೆ ಕಾಣುವುದು,',
9: 'ಆಸಕ್ತಿಯಿಲ್ಲದಿರುವಿಕೆ, ಮಗ, ಹೆಂಡತಿ, ಮನೆ ಮುಂತಾದವುಗಳೊಂದಿಗೆ ತನ್ನನ್ನು ಬೆಸೆದುಕೊಳ್ಳದಿರುವಿಕೆ, ಇಷ್ಟವಾದುದು ಮತ್ತು ಇಷ್ಟವಿಲ್ಲದ್ದು ನಡೆದಾಗ ಸದಾ ಸಮಚಿತ್ತವಾಗಿರುವುದು,',
10: 'ಅನನ್ಯ ಯೋಗದಿಂದ ನನ್ನಲ್ಲಿ ಅಚಲ ಭಕ್ತಿ, ಏಕಾಂತ ಸ್ಥಳದಲ್ಲಿ ವಾಸ, ಜನಸಂದಣಿಯಲ್ಲಿ ಆಸಕ್ತಿಯಿಲ್ಲದಿರುವಿಕೆ,',
11: 'ಆತ್ಮಜ್ಞಾನದಲ್ಲಿ ಸದಾ ನೆಲೆಸಿರುವುದು, ತತ್ತ್ವಜ್ಞಾನದ ಗುರಿಯನ್ನು ಕಾಣುವುದು: ಇದನ್ನೇ ಜ್ಞಾನ ಎನ್ನುತ್ತಾರೆ; ಇದಕ್ಕೆ ವಿರುದ್ಧವಾದುದು ಅಜ್ಞಾನ.',
12: 'ತಿಳಿಯಬೇಕಾದುದು ಯಾವುದೋ, ಯಾವುದನ್ನು ತಿಳಿದರೆ ಅಮೃತತ್ವ ಸಿಗುತ್ತದೋ, ಅದನ್ನು ಹೇಳುತ್ತೇನೆ. ಅದು ಅನಾದಿ ಪರಬ್ರಹ್ಮ; ಅದನ್ನು ಸತ್ ಎಂದೂ ಹೇಳಲಾಗದು, ಅಸತ್ ಎಂದೂ ಹೇಳಲಾಗದು.',
13: 'ಅದಕ್ಕೆ ಎಲ್ಲೆಡೆ ಕೈಕಾಲುಗಳು, ಎಲ್ಲೆಡೆ ಕಣ್ಣುಗಳು, ತಲೆಗಳು ಮತ್ತು ಮುಖಗಳು, ಎಲ್ಲೆಡೆ ಕಿವಿಗಳು. ಲೋಕದಲ್ಲಿ ಅದು ಎಲ್ಲವನ್ನೂ ಆವರಿಸಿ ನಿಂತಿದೆ.',
14: 'ಅದು ಎಲ್ಲ ಇಂದ್ರಿಯಗಳ ಗುಣಗಳಿಂದ ಹೊಳೆಯುತ್ತದೆ, ಆದರೂ ಎಲ್ಲ ಇಂದ್ರಿಯಗಳಿಗೂ ಅತೀತ. ಆಸಕ್ತಿಯಿಲ್ಲದಿದ್ದರೂ ಎಲ್ಲವನ್ನೂ ಧರಿಸುತ್ತದೆ; ಗುಣರಹಿತವಾದರೂ ಗುಣಗಳನ್ನು ಅನುಭವಿಸುತ್ತದೆ.',
15: 'ಅದು ಜೀವಿಗಳ ಹೊರಗೂ ಒಳಗೂ ಇದೆ, ಚಲಿಸದ್ದೂ ಚಲಿಸುವುದೂ ಅದೇ. ಅತಿ ಸೂಕ್ಷ್ಮವಾದ್ದರಿಂದ ಅದನ್ನು ತಿಳಿಯಲಾಗದು; ಅದು ದೂರದಲ್ಲಿದೆ, ಹತ್ತಿರದಲ್ಲೂ ಇದೆ.',
16: 'ವಿಭಾಗವಾಗದಿದ್ದರೂ ಅದು ಜೀವಿಗಳಲ್ಲಿ ವಿಭಾಗವಾದಂತೆ ಇದೆ. ಅದನ್ನು ಜೀವಿಗಳನ್ನು ಪೋಷಿಸುವುದು, ನುಂಗುವುದು ಮತ್ತು ಹುಟ್ಟಿಸುವುದು ಎಂದು ತಿಳಿಯಬೇಕು.',
17: 'ಅದು ಜ್ಯೋತಿಗಳಿಗೂ ಜ್ಯೋತಿ, ಕತ್ತಲೆಗೆ ಅತೀತ ಎನ್ನುತ್ತಾರೆ. ಅದು ಜ್ಞಾನ, ತಿಳಿಯಬೇಕಾದುದು, ಜ್ಞಾನದಿಂದ ಪಡೆಯಬೇಕಾದುದು; ಅದು ಎಲ್ಲರ ಹೃದಯದಲ್ಲಿದೆ.',
18: 'ಹೀಗೆ ಕ್ಷೇತ್ರ, ಜ್ಞಾನ ಮತ್ತು ತಿಳಿಯಬೇಕಾದುದನ್ನು ಸಂಕ್ಷೇಪವಾಗಿ ಹೇಳಲಾಯಿತು. ನನ್ನ ಭಕ್ತ ಇದನ್ನು ತಿಳಿದು ನನ್ನ ಭಾವವನ್ನು ಪಡೆಯುತ್ತಾನೆ.',
19: 'ಪ್ರಕೃತಿ ಮತ್ತು ಪುರುಷ ಇಬ್ಬರೂ ಅನಾದಿ ಎಂದು ತಿಳಿ. ವಿಕಾರಗಳು ಮತ್ತು ಗುಣಗಳೆಲ್ಲವೂ ಪ್ರಕೃತಿಯಿಂದಲೇ ಹುಟ್ಟುತ್ತವೆ ಎಂದು ತಿಳಿ.',
20: 'ಕಾರ್ಯ ಮತ್ತು ಸಾಧನಗಳು ಹುಟ್ಟಲು ಪ್ರಕೃತಿ ಕಾರಣ ಎನ್ನಲಾಗುತ್ತದೆ. ಸುಖ-ದುಃಖಗಳನ್ನು ಅನುಭವಿಸಲು ಪುರುಷ ಕಾರಣ ಎನ್ನಲಾಗುತ್ತದೆ.',
21: 'ಪ್ರಕೃತಿಯಲ್ಲಿರುವ ಪುರುಷ ಪ್ರಕೃತಿಯಿಂದ ಹುಟ್ಟಿದ ಗುಣಗಳನ್ನು ಅನುಭವಿಸುತ್ತಾನೆ. ಗುಣಗಳ ಮೇಲಿನ ಆಸಕ್ತಿಯೇ ಅವನು ಒಳ್ಳೆಯ ಮತ್ತು ಕೆಟ್ಟ ಜನ್ಮಗಳನ್ನು ಪಡೆಯಲು ಕಾರಣ.',
22: 'ಈ ದೇಹದಲ್ಲಿರುವ ಪರಮ ಪುರುಷ ಸಾಕ್ಷಿ, ಅನುಮತಿ ಕೊಡುವವನು, ಭರಿಸುವವನು, ಅನುಭವಿಸುವವನು, ಮಹೇಶ್ವರ; ಅವನನ್ನೇ ಪರಮಾತ್ಮ ಎಂದೂ ಕರೆಯುತ್ತಾರೆ.',
23: 'ಪುರುಷನನ್ನೂ ಗುಣಗಳೊಂದಿಗೆ ಪ್ರಕೃತಿಯನ್ನೂ ಹೀಗೆ ತಿಳಿದವನು, ಯಾವ ಸ್ಥಿತಿಯಲ್ಲಿದ್ದರೂ, ಮತ್ತೆ ಹುಟ್ಟುವುದಿಲ್ಲ.',
24: 'ಕೆಲವರು ಧ್ಯಾನದಿಂದ ತಮ್ಮೊಳಗೇ ತಮ್ಮ ಮನಸ್ಸಿನಿಂದ ಆತ್ಮವನ್ನು ಕಾಣುತ್ತಾರೆ; ಇನ್ನು ಕೆಲವರು ಸಾಂಖ್ಯಯೋಗದಿಂದ, ಮತ್ತೆ ಕೆಲವರು ಕರ್ಮಯೋಗದಿಂದ ಕಾಣುತ್ತಾರೆ.',
25: 'ಇನ್ನು ಕೆಲವರು ಹೀಗೆ ತಿಳಿಯದೆ, ಇತರರಿಂದ ಕೇಳಿ ಉಪಾಸಿಸುತ್ತಾರೆ. ಕೇಳಿದ್ದನ್ನೇ ಪರಮ ಆಶ್ರಯವೆಂದು ಭಾವಿಸುವ ಅವರೂ ಮೃತ್ಯುವನ್ನು ದಾಟುತ್ತಾರೆ.',
26: 'ಹೇ ಭರತಶ್ರೇಷ್ಠ, ಚರವಾಗಲಿ ಅಚರವಾಗಲಿ, ಯಾವ ಜೀವಿ ಹುಟ್ಟಿದರೂ ಅದು ಕ್ಷೇತ್ರ ಮತ್ತು ಕ್ಷೇತ್ರಜ್ಞರ ಸಂಯೋಗದಿಂದಲೇ ಎಂದು ತಿಳಿ.',
28: 'ಎಲ್ಲೆಡೆ ಸಮನಾಗಿರುವ ಈಶ್ವರನನ್ನು ಸಮವಾಗಿ ಕಾಣುವವನು ತನ್ನಿಂದ ತನ್ನನ್ನು ಹಿಂಸಿಸಿಕೊಳ್ಳುವುದಿಲ್ಲ. ಆದ್ದರಿಂದ ಅವನು ಪರಮ ಗತಿಯನ್ನು ಸೇರುತ್ತಾನೆ.',
29: 'ಎಲ್ಲ ಕರ್ಮಗಳೂ ಪ್ರಕೃತಿಯಿಂದಲೇ ನಡೆಯುತ್ತಿವೆ, ಆತ್ಮ ಕರ್ತನಲ್ಲ ಎಂದು ಕಾಣುವವನೇ ನಿಜವಾಗಿ ಕಾಣುತ್ತಾನೆ.',
30: 'ಜೀವಿಗಳ ಬೇರೆ ಬೇರೆ ಭಾವಗಳು ಒಂದರಲ್ಲೇ ಇವೆ, ಅದರಿಂದಲೇ ವಿಸ್ತರಿಸಿವೆ ಎಂದು ಕಂಡಾಗ ಅವನು ಬ್ರಹ್ಮವನ್ನು ಸೇರುತ್ತಾನೆ.',
31: 'ಹೇ ಕೌಂತೇಯ, ಅನಾದಿಯೂ ಗುಣರಹಿತವೂ ಆದ್ದರಿಂದ ಈ ಅವಿನಾಶಿ ಪರಮಾತ್ಮ ದೇಹದಲ್ಲಿದ್ದರೂ ಕರ್ಮ ಮಾಡುವುದಿಲ್ಲ, ಅದಕ್ಕೆ ಅಂಟಿಕೊಳ್ಳುವುದೂ ಇಲ್ಲ.',
32: 'ಎಲ್ಲೆಡೆ ವ್ಯಾಪಿಸಿರುವ ಆಕಾಶ ಸೂಕ್ಷ್ಮವಾದ್ದರಿಂದ ಯಾವುದಕ್ಕೂ ಅಂಟಿಕೊಳ್ಳದಂತೆ, ದೇಹವೆಲ್ಲ ಇರುವ ಆತ್ಮ ಯಾವುದಕ್ಕೂ ಅಂಟಿಕೊಳ್ಳುವುದಿಲ್ಲ.',
33: 'ಹೇ ಭಾರತ, ಒಬ್ಬನೇ ಸೂರ್ಯ ಈ ಇಡೀ ಲೋಕವನ್ನು ಬೆಳಗುವಂತೆ, ಕ್ಷೇತ್ರಜ್ಞ ಇಡೀ ಕ್ಷೇತ್ರವನ್ನು ಬೆಳಗುತ್ತಾನೆ.',
34: 'ಜ್ಞಾನದ ಕಣ್ಣಿನಿಂದ ಕ್ಷೇತ್ರ ಮತ್ತು ಕ್ಷೇತ್ರಜ್ಞರ ನಡುವಿನ ವ್ಯತ್ಯಾಸವನ್ನೂ, ಜೀವಿಗಳು ಪ್ರಕೃತಿಯಿಂದ ಮುಕ್ತರಾಗುವುದನ್ನೂ ಹೀಗೆ ತಿಳಿದವರು ಪರಮಾತ್ಮನನ್ನು ಸೇರುತ್ತಾರೆ.',
}
